{
  "version": "1.2.0",
  "riskTierRules": {
    ".github/workflows/**": "high",
    "scripts/**": "high",
    "docs/agents/**": "medium",
    "**/SKILL.md": "medium",
    "README.md": "low"
  },
  "mergePolicy": {
    "high": [
      "review-gate",
      "evidence-verify"
    ],
    "medium": [
      "review-gate"
    ],
    "low": []
  },
  "docsDriftRules": {},
  "reviewPolicy": {
    "timeoutSeconds": 600,
    "timeoutAction": "fail",
    "requiredChecks": [
      "security-scan"
    ],
    "enforceReviewerIndependence": false
  },
  "evidencePolicy": {
    "requiredFor": [],
    "allowedTypes": [
      "png",
      "jpeg"
    ],
    "maxFileSizeBytes": 1048576
  },
  "diffBudget": {
    "maxFiles": 10,
    "maxNetLOC": 400,
    "overrideLabel": "diff-budget-override"
  },
  "uiLoopPolicy": {
    "fastCommand": "just status",
    "verifyCommand": "just validate",
    "exploreCommand": "python3 scripts/diagnose_skill.py --all",
    "sloTargets": {
      "fastLoopSeconds": 30,
      "verifyLoopSeconds": 120
    }
  },
  "runtimePolicy": {
    "nodeVersion": "25.x",
    "createIssueOnAgentFindings": true
  },
  "memoryPolicy": {
    "enabled": true,
    "provider": "local",
    "sessionIdTemplate": "repo:<name>:task:<id>",
    "domain": "default",
    "requiredTags": [
      "repo",
      "area",
      "type"
    ],
    "maxObservationsPerStep": 3,
    "allowedLevels": [
      "observation",
      "learning",
      "pattern"
    ],
    "requireStartRead": true,
    "requireCloseoutSummary": true,
    "forbiddenContentPatterns": [
      "token",
      "api[_-]?key",
      "secret",
      "password",
      "credential"
    ]
  },
  "memoryMaintenancePolicy": {
    "validateSchedule": "weekly",
    "reflectSchedule": "weekly",
    "questionSlaDays": 7,
    "duplicateThreshold": 0.8
  },
  "memoryEvalPolicy": {
    "trialsPerTask": 3,
    "requiredMetrics": [
      "pass^k",
      "tool_errors",
      "duplicate_rate"
    ],
    "passPowKThreshold": 0.8
  },
  "observabilityPolicy": {
    "provider": "logs",
    "collectorEndpoint": "http://localhost:4318"
  },
  "packageManagerPolicy": {
    "allowedManagers": [
      "pnpm",
      "npm",
      "yarn"
    ],
    "requiredManager": null
  },
  "remediationPolicy": {
    "providerDefaults": {
      "greptile": {
        "autoApplyMaxTier": "medium",
        "dryRunOnlyByDefault": false
      },
      "codex": {
        "autoApplyMaxTier": "medium",
        "dryRunOnlyByDefault": false
      }
    },
    "marker": "[auto-remediate]",
    "timeoutMinutes": 10,
    "retryLimit": 3,
    "requireEvidence": true
  },
  "loopStageContracts": {
    "risk-policy-gate": {
      "inputs": [
        "changed_files",
        "harness.contract.json"
      ],
      "outputs": [
        "risk-policy-gate.result"
      ],
      "schema": "loop-stage-contract/v1",
      "failPolicy": "fail_closed",
      "if": "always()",
      "permissions": [
        "contents:read",
        "pull-requests:read"
      ],
      "timeoutMinutes": 15,
      "concurrency": "none"
    },
    "review-gate": {
      "inputs": [
        "risk-policy-gate.result",
        "head_sha",
        "harness.contract.json"
      ],
      "outputs": [
        "review-gate.result"
      ],
      "schema": "loop-stage-contract/v1",
      "failPolicy": "fail_closed",
      "if": "always()",
      "permissions": [
        "contents:read",
        "pull-requests:read"
      ],
      "timeoutMinutes": 15,
      "concurrency": "none"
    },
    "evidence-verify": {
      "inputs": [
        "review-gate.result",
        "evidence_files",
        "harness.contract.json"
      ],
      "outputs": [
        "evidence-verify.result",
        "browser-evidence-artifacts"
      ],
      "schema": "loop-stage-contract/v1",
      "failPolicy": "fail_closed",
      "if": "always()",
      "permissions": [
        "contents:read"
      ],
      "timeoutMinutes": 15,
      "concurrency": "none"
    },
    "remediation-decision": {
      "inputs": [
        "evidence-verify.result",
        "findings.json",
        "harness.contract.json"
      ],
      "outputs": [
        "remediation-decision.result",
        "remediation-decision-artifacts"
      ],
      "schema": "loop-stage-contract/v1",
      "failPolicy": "fail_closed",
      "if": "always()",
      "permissions": [
        "contents:read",
        "pull-requests:write"
      ],
      "timeoutMinutes": 15,
      "concurrency": "none"
    }

